output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles that are too narrow for two cells of horizontal clearance.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "An agent must not move into a single-file aisle while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "cart_drop_only_for_single_file_visit",
    "text": "If an agent parks or drops a cart, they are obliged to enter a single-file aisle on foot before leaving the parking context.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "enterSingleFileOnFoot"
    }
  },
  {
    "id": "retrieve_cart_after_single_file_aisle",
    "text": "After returning from a single-file aisle without a cart, the agent is obliged to pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartCompatibleArea": {
          "gt": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "exitSingleFileOnFoot": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              },
              "singleFileAisle"
            ]
          },
          "post": {
            "and": [
              "cartCompatibleArea",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "cartPickup": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "exitSingleFileOnFoot",
      "discharge": "cartPickup"
    }
  },
  {
    "id": "cart_required_at_accessible_shelves",
    "text": "When interacting with a shelf from a cart-accessible aisle, the agent must have the cart.",
    "abstraction": {
      "state_properties": {
        "cartAccessibleShelf": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelf",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "hand_carry_in_single_file_shelf_aisles",
    "text": "Shelf interactions inside single-file shelf aisles must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "pedestrianShelfAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "pedestrianShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cartless_wandering_in_cart_lanes",
    "text": "Away from the single-file aisles, cart-lane movement without a cart is prohibited unless the move is the actual entry into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartLane": {
          "gt": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "cartLane",
          {
            "not": "enterSingleFileOnFoot"
          }
        ]
      }
    }
  },
  {
    "id": "leave_cart_shelf_by_backing_away",
    "text": "After interacting with a cart-accessible shelf, the agent is obliged to move away from the side on which that shelf is located.",
    "abstraction": {
      "state_properties": {
        "cartAccessibleShelf": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartAccessibleShelfInteract": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "cartAccessibleShelf"
            ]
          },
          "post": null
        },
        "moveAwayFromAdjacentShelf": {
          "pre": {
            "or": [
              {
                "and": [
                  "shelfN",
                  "S"
                ]
              },
              {
                "and": [
                  "shelfS",
                  "N"
                ]
              },
              {
                "and": [
                  "shelfW",
                  "E"
                ]
              },
              {
                "and": [
                  "shelfE",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartAccessibleShelfInteract",
      "discharge": "moveAwayFromAdjacentShelf"
    }
  }
]
